import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Kernel 日报 2026-11-22","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/22.md","filePath":"notes/kernel-digest/2026/11/22.md"}'),n={name:"notes/kernel-digest/2026/11/22.md"};function l(s,e,d,i,c,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-22" tabindex="-1">Kernel 日报 2026-11-22 <a class="header-anchor" href="#kernel-日报-2026-11-22" aria-label="Permalink to &quot;Kernel 日报 2026-11-22&quot;">​</a></h1><blockquote><p>生成时间：2026-11-22T02:47:27Z｜共 41 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-22 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="f005b9b41105-·-patch-net-0-2-vmxnet3-fix-native-xdp-crash-on-oversized-frames-and-xdp-loss-on-reset" tabindex="-1"><code>f005b9b41105</code> · <a href="https://lore.kernel.org/all/20261122002847.616-1-filzador@gmail.com/" target="_blank" rel="noreferrer">[PATCH net 0/2] vmxnet3: fix native XDP crash on oversized frames and XDP loss on reset</a> <a class="header-anchor" href="#f005b9b41105-·-patch-net-0-2-vmxnet3-fix-native-xdp-crash-on-oversized-frames-and-xdp-loss-on-reset" aria-label="Permalink to &quot;`f005b9b41105` · [[PATCH net 0/2] vmxnet3: fix native XDP crash on oversized frames and XDP loss on reset](https://lore.kernel.org/all/20261122002847.616-1-filzador@gmail.com/)&quot;">​</a></h3><p><em>Philipp Sudakas (<a href="mailto:filzador@gmail.com" target="_blank" rel="noreferrer">filzador@gmail.com</a>)｜netdev｜网络</em></p><p>本系列修复 vmxnet3 native XDP 模式的两个 bug：其一，同网段任意主机发送一个超长帧（MTU 1500 时 1523-1526 字节即可）即可让 guest 内核崩溃；其二，任何设备 reset（MTU 变更、down/up、ring resize 等）后驱动静默停止执行 XDP 并泄漏程序引用。</p><blockquote><p><strong>学习价值</strong>：一个系列同时覆盖安全相关的远程崩溃漏洞和状态管理泄漏，对理解驱动 XDP 实现中的边界条件很有教学价值。</p></blockquote><h3 id="ca8419d3f89d-·-patch-net-next-v2-0-9-net-make-core-auto-disable-hw-gro-and-lro-when-xdp-gets-attached" tabindex="-1"><code>ca8419d3f89d</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-1-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 0/9] net: make core auto-disable HW-GRO and LRO when XDP gets attached</a> <a class="header-anchor" href="#ca8419d3f89d-·-patch-net-next-v2-0-9-net-make-core-auto-disable-hw-gro-and-lro-when-xdp-gets-attached" aria-label="Permalink to &quot;`ca8419d3f89d` · [[PATCH net-next v2 0/9] net: make core auto-disable HW-GRO and LRO when XDP gets attached](https://lore.kernel.org/all/20261122010112.1471146-1-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev｜网络</em></p><p>本系列补丁将 XDP 挂载时自动清除 HW-GRO 和 LRO 的逻辑从各驱动上移到 netdev core，实现统一行为。原因在于 XDP 不理解 GSO 帧：GSO 帧在 XDP 看来只是大包，push/pop 头部操作无法反映到 GSO 元数据，且 struct xdp_frame 不携带 GSO 字段导致 XDP redirect 对 GSO 完全无感知。此前各驱动行为不一，有的拒绝挂载、有的自动清除。</p><blockquote><p><strong>学习价值</strong>：清晰解释了 XDP 与 GSO/GRO 的根本冲突，是理解 XDP 数据模型限制及其与 offload 交互的核心阅读材料。</p></blockquote><h3 id="_4ded74b952b1-·-patch-v16-00-19-hid-asus-add-support-for-rog-ally-handhelds" tabindex="-1"><code>4ded74b952b1</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-1-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 00/19] HID: asus: add support for ROG Ally handhelds</a> <a class="header-anchor" href="#_4ded74b952b1-·-patch-v16-00-19-hid-asus-add-support-for-rog-ally-handhelds" aria-label="Permalink to &quot;`4ded74b952b1` · [[PATCH v16 00/19] HID: asus: add support for ROG Ally handhelds](https://lore.kernel.org/all/20261122021849.57863-1-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml｜其他动态</em></p><p>该补丁系列（共 19 个 patch）为 ASUS ROG Ally 掌机在 HID 驱动中添加完整支持，包括睡眠唤醒后的设备重初始化、gamepad 配置、振动强度、摇杆与扳机范围、anti-deadzone、response curve、force feedback、手柄模式切换、turbo 按钮和按键重映射等功能。基于 Luke Jones 的原始工作重构为可上游合入的形式。</p><blockquote><p><strong>学习价值</strong>：作为完整的驱动补丁系列，展示了从功能设计、代码重构到 uAPI 暴露的完整上游流程，适合学习大型驱动补丁的组织方式。</p></blockquote><h3 id="_68df655238ec-·-rfc-patch-v6-21-26-security-add-userland-lsm-hooks" tabindex="-1"><code>68df655238ec</code> · <a href="https://lore.kernel.org/all/20261122011809.2667684-22-jarkko@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH v6 21/26] security: Add userland LSM hooks</a> <a class="header-anchor" href="#_68df655238ec-·-rfc-patch-v6-21-26-security-add-userland-lsm-hooks" aria-label="Permalink to &quot;`68df655238ec` · [[RFC PATCH v6 21/26] security: Add userland LSM hooks](https://lore.kernel.org/all/20261122011809.2667684-22-jarkko@kernel.org/)&quot;">​</a></h3><p><em>Jarkko Sakkinen (<a href="mailto:jarkko@kernel.org" target="_blank" rel="noreferrer">jarkko@kernel.org</a>)｜linux-mm｜内存管理</em></p><p>该补丁为 LSM 框架新增 userland 钩子：lbs_userland 安全 blob 管理以及 security_userland_alloc/free/share/clone/kill() 等接口，覆盖 userland 的创建、销毁、namespace 共享、进程进入和信号投递。安全模块由此可以附加 per-userland 安全状态并对 userland 文件描述符的操作进行仲裁。</p><blockquote><p><strong>学习价值</strong>：是理解 LSM 钩子定义（lsm_hook_defs.h）与 security blob 生命周期管理的典型范例。</p></blockquote><h3 id="_26fd8c00840c-·-patch-v2-rust-binder-disallow-binder-fd-transfers" tabindex="-1"><code>26fd8c00840c</code> · <a href="https://lore.kernel.org/all/20261121182803.2600723-1-cmllamas@google.com/" target="_blank" rel="noreferrer">[PATCH v2] rust_binder: disallow binder fd transfers</a> <a class="header-anchor" href="#_26fd8c00840c-·-patch-v2-rust-binder-disallow-binder-fd-transfers" aria-label="Permalink to &quot;`26fd8c00840c` · [[PATCH v2] rust_binder: disallow binder fd transfers](https://lore.kernel.org/all/20261121182803.2600723-1-cmllamas@google.com/)&quot;">​</a></h3><p><em>Carlos Llamas (<a href="mailto:cmllamas@google.com" target="_blank" rel="noreferrer">cmllamas@google.com</a>)｜rust-for-linux｜Rust in Linux</em></p><p>通过 BINDER_TYPE_FD 或 BINDER_TYPE_FDA 转移 binder 设备 fd 没有合法用例，且会创建引用循环，导致排队的 transaction 未读时 Process::release() 无法执行；binder 文件还绑定到打开进程的 task、credentials 和 mmap 状态，跨进程转移破坏其 per-process 所有权模型。补丁在 Allocation::info_add_fd() 中返回 EINVAL 以禁止此类转移。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 实现中如何用简单拒绝策略消除引用循环与所有权违规，对理解 binder 生命周期模型和 Rust for Linux 的安全设计都有帮助。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（7 条）</li><li><strong>网络</strong>（15 条）</li><li><strong>文件系统与存储</strong>（1 条）</li><li><strong>Rust in Linux</strong>（2 条）</li><li><strong>跟踪与性能</strong>（1 条）</li><li><strong>其他动态</strong>（15 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="_7becb5959b56-·-rfc-patch-v6-26-26-maintainers-add-entry-for-userland" tabindex="-1"><code>7becb5959b56</code> · <a href="https://lore.kernel.org/all/20261122011809.2667684-27-jarkko@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH v6 26/26] MAINTAINERS: Add entry for USERLAND</a> <a class="header-anchor" href="#_7becb5959b56-·-rfc-patch-v6-26-26-maintainers-add-entry-for-userland" aria-label="Permalink to &quot;`7becb5959b56` · [[RFC PATCH v6 26/26] MAINTAINERS: Add entry for USERLAND](https://lore.kernel.org/all/20261122011809.2667684-27-jarkko@kernel.org/)&quot;">​</a></h3><p><em>Jarkko Sakkinen (<a href="mailto:jarkko@kernel.org" target="_blank" rel="noreferrer">jarkko@kernel.org</a>)｜linux-mm</em></p><p>该补丁在 MAINTAINERS 文件中为 USERLAND 子系统新增维护者条目，由 David Howells 和 Jarkko Sakkinen 维护，涵盖 uAPI headers、核心实现、文档和 selftests，邮件列表路由到 linux-fsdevel。</p><blockquote><p><strong>学习价值</strong>：展示了新子系统进入内核时 MAINTAINERS 文件的维护规范，了解内核社区的管理流程。</p></blockquote><h3 id="_80b6ce54407f-·-rfc-patch-v6-25-26-selftests-userland-add-userland-test-suite" tabindex="-1"><code>80b6ce54407f</code> · <a href="https://lore.kernel.org/all/20261122011809.2667684-26-jarkko@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH v6 25/26] selftests/userland: Add userland test suite</a> <a class="header-anchor" href="#_80b6ce54407f-·-rfc-patch-v6-25-26-selftests-userland-add-userland-test-suite" aria-label="Permalink to &quot;`80b6ce54407f` · [[RFC PATCH v6 25/26] selftests/userland: Add userland test suite](https://lore.kernel.org/all/20261122011809.2667684-26-jarkko@kernel.org/)&quot;">​</a></h3><p><em>Jarkko Sakkinen (<a href="mailto:jarkko@kernel.org" target="_blank" rel="noreferrer">jarkko@kernel.org</a>)｜linux-mm</em></p><p>该补丁为 userland 子系统添加 selftests 测试套件，验证 userland_open() 控制对象、namespace 共享、mount-namespace 配置、waitid(P_USERLAND)、pidfd_send_signal() 和 userns_set_idmap() 等 uAPI 及安全不变量，覆盖特权、非特权、SCM_RIGHTS 委托和边界场景。</p><blockquote><p><strong>学习价值</strong>：展示了内核新 uAPI 如何通过 selftests 验证安全不变量，对学习 pidfd、user namespace 与测试框架设计都很有价值。</p></blockquote><h3 id="_7d315f05c477-·-rfc-patch-v6-24-26-docs-document-userland-uapi" tabindex="-1"><code>7d315f05c477</code> · <a href="https://lore.kernel.org/all/20261122011809.2667684-25-jarkko@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH v6 24/26] docs: Document userland uAPI</a> <a class="header-anchor" href="#_7d315f05c477-·-rfc-patch-v6-24-26-docs-document-userland-uapi" aria-label="Permalink to &quot;`7d315f05c477` · [[RFC PATCH v6 24/26] docs: Document userland uAPI](https://lore.kernel.org/all/20261122011809.2667684-25-jarkko@kernel.org/)&quot;">​</a></h3><p><em>Jarkko Sakkinen (<a href="mailto:jarkko@kernel.org" target="_blank" rel="noreferrer">jarkko@kernel.org</a>)｜linux-mm</em></p><p>该补丁添加 Documentation/userspace-api/userland.rst，为 userspace 编排器提供 userland 的完整规范，包括构建与运行状态转换、USERLAND_GET_NSFD、USERLAND_SHARE_NSFD、waitid(P_USERLAND)、pidfd_send_signal()、mount-tree 构建、user namespace ID 映射、凭证规则和进程创建语义。</p><blockquote><p><strong>学习价值</strong>：体现了内核 uAPI 文档化的标准做法（kernel-doc 与 rst 结合），是学习新系统调用/接口文档规范的参考。</p></blockquote><h3 id="_7cb797d11e0f-·-rfc-patch-v6-23-26-arch-wire-up-userland-open-system-call" tabindex="-1"><code>7cb797d11e0f</code> · <a href="https://lore.kernel.org/all/20261122011809.2667684-24-jarkko@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH v6 23/26] arch: Wire up userland_open() system call</a> <a class="header-anchor" href="#_7cb797d11e0f-·-rfc-patch-v6-23-26-arch-wire-up-userland-open-system-call" aria-label="Permalink to &quot;`7cb797d11e0f` · [[RFC PATCH v6 23/26] arch: Wire up userland_open() system call](https://lore.kernel.org/all/20261122011809.2667684-24-jarkko@kernel.org/)&quot;">​</a></h3><p><em>Jarkko Sakkinen (<a href="mailto:jarkko@kernel.org" target="_blank" rel="noreferrer">jarkko@kernel.org</a>)｜linux-mm</em></p><p>该补丁为新的 userland_open() 系统调用（编号 474，Alpha 上为 584）在所有架构的系统调用表、asm-generic unistd.h 以及 tools/ 下的镜像副本中完成接线。这是 userland 生命周期与 VFS mount-tree 安装机制落地后的暴露步骤。</p><blockquote><p><strong>学习价值</strong>：学习系统调用如何跨架构统一添加的完整流程，是理解 syscall 接线机制的绝佳实例。</p></blockquote><h3 id="_8c34f0031109-·-rfc-patch-v6-22-26-bpf-register-userland-lsm-hooks" tabindex="-1"><code>8c34f0031109</code> · <a href="https://lore.kernel.org/all/20261122011809.2667684-23-jarkko@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH v6 22/26] bpf: Register userland LSM hooks</a> <a class="header-anchor" href="#_8c34f0031109-·-rfc-patch-v6-22-26-bpf-register-userland-lsm-hooks" aria-label="Permalink to &quot;`8c34f0031109` · [[RFC PATCH v6 22/26] bpf: Register userland LSM hooks](https://lore.kernel.org/all/20261122011809.2667684-23-jarkko@kernel.org/)&quot;">​</a></h3><p><em>Jarkko Sakkinen (<a href="mailto:jarkko@kernel.org" target="_blank" rel="noreferrer">jarkko@kernel.org</a>)｜linux-mm</em></p><p>该补丁在 kernel/bpf/bpf_lsm.c 中将 userland 相关的 LSM 钩子注册到 BPF LSM 分类中：bpf_lsm_userland_alloc/share/clone/kill 加入 sleepable_lsm_hooks，bpf_lsm_userland_alloc/free 加入 untrusted_lsm_hooks，均在 CONFIG_USERLAND 下。这样 BPF LSM 程序就能对 userland 的分配、共享、克隆、信号和释放附加策略。</p><blockquote><p><strong>学习价值</strong>：展示了 BPF LSM 钩子的 sleepable/untrusted 分类机制，是学习 eBPF 与 LSM 集成的实用参考。</p></blockquote><h3 id="_68df655238ec-·-rfc-patch-v6-21-26-security-add-userland-lsm-hooks-1" tabindex="-1"><code>68df655238ec</code> · <a href="https://lore.kernel.org/all/20261122011809.2667684-22-jarkko@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH v6 21/26] security: Add userland LSM hooks</a> <a class="header-anchor" href="#_68df655238ec-·-rfc-patch-v6-21-26-security-add-userland-lsm-hooks-1" aria-label="Permalink to &quot;`68df655238ec` · [[RFC PATCH v6 21/26] security: Add userland LSM hooks](https://lore.kernel.org/all/20261122011809.2667684-22-jarkko@kernel.org/)&quot;">​</a></h3><p><em>Jarkko Sakkinen (<a href="mailto:jarkko@kernel.org" target="_blank" rel="noreferrer">jarkko@kernel.org</a>)｜linux-mm</em></p><p>该补丁为 LSM 框架新增 userland 钩子：lbs_userland 安全 blob 管理以及 security_userland_alloc/free/share/clone/kill() 等接口，覆盖 userland 的创建、销毁、namespace 共享、进程进入和信号投递。安全模块由此可以附加 per-userland 安全状态并对 userland 文件描述符的操作进行仲裁。</p><blockquote><p><strong>学习价值</strong>：是理解 LSM 钩子定义（lsm_hook_defs.h）与 security blob 生命周期管理的典型范例。</p></blockquote><h3 id="_4faa2ccfdd93-·-rfc-patch-v6-20-26-ipc-mqueue-implement-set-userland-fs-context-operation" tabindex="-1"><code>4faa2ccfdd93</code> · <a href="https://lore.kernel.org/all/20261122011809.2667684-21-jarkko@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH v6 20/26] ipc/mqueue: Implement -&gt;set_userland() fs_context operation</a> <a class="header-anchor" href="#_4faa2ccfdd93-·-rfc-patch-v6-20-26-ipc-mqueue-implement-set-userland-fs-context-operation" aria-label="Permalink to &quot;`4faa2ccfdd93` · [[RFC PATCH v6 20/26] ipc/mqueue: Implement -&gt;set_userland() fs_context operation](https://lore.kernel.org/all/20261122011809.2667684-21-jarkko@kernel.org/)&quot;">​</a></h3><p><em>Jarkko Sakkinen (<a href="mailto:jarkko@kernel.org" target="_blank" rel="noreferrer">jarkko@kernel.org</a>)｜linux-mm</em></p><p>该补丁为 mqueue 实现 -&gt;set_userland() fs_context 操作：mqueue_init_fs_context() 原本固定绑定调用者的 IPC namespace，现在通过 mqueue_set_userland() 将 ctx-&gt;ipc_ns 切换到目标 userland 的 IPC namespace，并同步更新 fc-&gt;user_ns，同时为 mqueue 标记 FS_USERLAND_MOUNT。</p><blockquote><p><strong>学习价值</strong>：有助于理解 fs_context、user namespace 与 IPC namespace 之间的绑定关系及 mount 时的重绑定逻辑。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_5e7e33b43de4-·-patch-net-v2-ipv6-fix-ioam6-id-wide-sysctl-on-32-bit-architectures" tabindex="-1"><code>5e7e33b43de4</code> · <a href="https://lore.kernel.org/all/20261122013848.14287-1-jain.sm@gmail.com/" target="_blank" rel="noreferrer">[PATCH net v2] ipv6: fix ioam6_id_wide sysctl on 32-bit architectures</a> <a class="header-anchor" href="#_5e7e33b43de4-·-patch-net-v2-ipv6-fix-ioam6-id-wide-sysctl-on-32-bit-architectures" aria-label="Permalink to &quot;`5e7e33b43de4` · [[PATCH net v2] ipv6: fix ioam6_id_wide sysctl on 32-bit architectures](https://lore.kernel.org/all/20261122013848.14287-1-jain.sm@gmail.com/)&quot;">​</a></h3><p><em>Shashank Mohan Jain (<a href="mailto:jain.sm@gmail.com" target="_blank" rel="noreferrer">jain.sm@gmail.com</a>)｜netdev</em></p><p>修复 net.ipv6.ioam6_id_wide sysctl 在 32 位架构上的 bug：该字段是 u64，但表项使用 proc_doulongvec_minmax()，而 32 位上 unsigned long 只有 4 字节，导致读取时打印两个数字、写入时只替换 u64 的一半且范围检查错误。</p><blockquote><p><strong>学习价值</strong>：经典的数据类型宽度不匹配 bug，提醒学习者 sysctl handler 必须与字段实际类型严格对应。</p></blockquote><h3 id="_47cad41c73da-·-patch-net-next-v2-8-9-eth-qede-drop-the-now-dead-hw-gro-vs-xdp-handling" tabindex="-1"><code>47cad41c73da</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-9-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 8/9] eth: qede: drop the now-dead HW-GRO vs XDP handling</a> <a class="header-anchor" href="#_47cad41c73da-·-patch-net-next-v2-8-9-eth-qede-drop-the-now-dead-hw-gro-vs-xdp-handling" aria-label="Permalink to &quot;`47cad41c73da` · [[PATCH net-next v2 8/9] eth: qede: drop the now-dead HW-GRO vs XDP handling](https://lore.kernel.org/all/20261122010112.1471146-9-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>由于核心层现在会在 ndo_bpf 运行前清除 HW-GRO 并在 XDP 程序挂载期间保持关闭，qede 驱动中两处 HW-GRO 与 XDP 互斥处理代码已成死代码，本补丁将其删除。qede_alloc_mem_rxq() 中直接清除 NETIF_F_GRO_HW 的写法保留，以应对固件恢复重跑 qede_init_ndev() 的场景。</p><blockquote><p><strong>学习价值</strong>：展示了核心层统一策略后驱动代码清理的思路，理解 feature 协商与驱动状态机的交互。</p></blockquote><h3 id="_60cf239f4d06-·-patch-net-next-v2-9-9-eth-gve-drop-the-now-dead-hw-gro-vs-xdp-interlock" tabindex="-1"><code>60cf239f4d06</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-10-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 9/9] eth: gve: drop the now-dead HW-GRO vs XDP interlock</a> <a class="header-anchor" href="#_60cf239f4d06-·-patch-net-next-v2-9-9-eth-gve-drop-the-now-dead-hw-gro-vs-xdp-interlock" aria-label="Permalink to &quot;`60cf239f4d06` · [[PATCH net-next v2 9/9] eth: gve: drop the now-dead HW-GRO vs XDP interlock](https://lore.kernel.org/all/20261122010112.1471146-10-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>核心层已在 XDP 程序挂载期间强制关闭 NETIF_F_GRO_HW，gve 驱动中 gve_verify_xdp_configuration() 等互斥检查代码不再可能触发，本补丁将其移除。用户可见行为按预期改变：在开启 HW-GRO 的 gve 设备上挂载 XDP 不再返回 -EOPNOTSUPP，而是关闭 HW-GRO 后成功，与 bnxt 和 qede 的行为一致。</p><blockquote><p><strong>学习价值</strong>：演示了核心策略统一后各驱动行为收敛的过程，对理解 XDP 与硬件 offload 的互斥关系很有价值。</p></blockquote><h3 id="_78127c164419-·-patch-net-next-v2-7-9-eth-bnxt-en-don-t-clear-hw-gro-and-lro-for-xdp-in-ndo-fix-features" tabindex="-1"><code>78127c164419</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-8-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 7/9] eth: bnxt_en: don&#39;t clear HW-GRO and LRO for XDP in ndo_fix_features</a> <a class="header-anchor" href="#_78127c164419-·-patch-net-next-v2-7-9-eth-bnxt-en-don-t-clear-hw-gro-and-lro-for-xdp-in-ndo-fix-features" aria-label="Permalink to &quot;`78127c164419` · [[PATCH net-next v2 7/9] eth: bnxt_en: don&#39;t clear HW-GRO and LRO for XDP in ndo_fix_features](https://lore.kernel.org/all/20261122010112.1471146-8-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>核心层在 XDP 程序挂载期间持续保持 HW-GRO 和 LRO 关闭，因此 bnxt_fix_features() 中的 xdp_prog 检查不再影响结果，本补丁将其移除。无 agg rings 时两种 offload 均无法工作的限制部分保留。</p><blockquote><p><strong>学习价值</strong>：说明 ndo_fix_features 回调与核心 feature 协商的职责边界，适合学习网卡 feature 协商机制。</p></blockquote><h3 id="_797dfc5be2f6-·-patch-net-next-v2-6-9-eth-mlx5e-drop-the-now-dead-hw-gro-and-lro-vs-xdp-handling" tabindex="-1"><code>797dfc5be2f6</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-7-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 6/9] eth: mlx5e: drop the now-dead HW-GRO and LRO vs XDP handling</a> <a class="header-anchor" href="#_797dfc5be2f6-·-patch-net-next-v2-6-9-eth-mlx5e-drop-the-now-dead-hw-gro-and-lro-vs-xdp-handling" aria-label="Permalink to &quot;`797dfc5be2f6` · [[PATCH net-next v2 6/9] eth: mlx5e: drop the now-dead HW-GRO and LRO vs XDP handling](https://lore.kernel.org/all/20261122010112.1471146-7-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>核心层在 ndo_bpf 之前清除 HW-GRO 和 LRO 并在程序挂载期间保持关闭，mlx5e_fix_features() 和 mlx5e_xdp_set() 中的相关处理已成死代码，本补丁删除。若 tcp-data-split 使 HW-GRO 保持开启，核心层会在调用驱动前以 -EBUSY 拒绝挂载。</p><blockquote><p><strong>学习价值</strong>：通过 mlx5e 的清理案例展示 XDP 挂载路径上核心与驱动的分工，加深对 netdev feature 生命周期的理解。</p></blockquote><h3 id="_5e2acb9fd8f7-·-patch-net-next-v2-5-9-net-state-the-xdp-excludes-lro-rule-in-the-core" tabindex="-1"><code>5e2acb9fd8f7</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-6-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 5/9] net: state the &quot;XDP excludes LRO&quot; rule in the core</a> <a class="header-anchor" href="#_5e2acb9fd8f7-·-patch-net-next-v2-5-9-net-state-the-xdp-excludes-lro-rule-in-the-core" aria-label="Permalink to &quot;`5e2acb9fd8f7` · [[PATCH net-next v2 5/9] net: state the &quot;XDP excludes LRO&quot; rule in the core](https://lore.kernel.org/all/20261122010112.1471146-6-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>该补丁将 &quot;XDP 排斥 LRO&quot; 的规则统一到网络核心层：与 HW-GRO 类似，XDP 无法处理 LRO 聚合后的帧，此前各驱动自行实现互斥且行为不一致（mlx5/netvsc 拒绝挂载、bnxt/ixgbe 在 fix_features 中清除、vmxnet3 直接改写 dev-&gt;features）。现在核心层在清除 HW-GRO 的同时清除 LRO，驱动坚持保留时同样拒绝挂载。</p><blockquote><p><strong>学习价值</strong>：是学习核心层统一驱动行为差异这一重构模式的优秀案例，体现 netdev 子系统的演进方向。</p></blockquote><h3 id="_34548a20143f-·-patch-net-next-v2-4-9-net-state-the-xdp-excludes-hw-gro-rule-in-the-core" tabindex="-1"><code>34548a20143f</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-5-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 4/9] net: state the &quot;XDP excludes HW-GRO&quot; rule in the core</a> <a class="header-anchor" href="#_34548a20143f-·-patch-net-next-v2-4-9-net-state-the-xdp-excludes-hw-gro-rule-in-the-core" aria-label="Permalink to &quot;`34548a20143f` · [[PATCH net-next v2 4/9] net: state the &quot;XDP excludes HW-GRO&quot; rule in the core](https://lore.kernel.org/all/20261122010112.1471146-5-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>该补丁将 &quot;XDP 排除 HW-GRO&quot; 的规则从各驱动上移到 netdev core：XDP 程序必须看到线缆原始帧，因此挂载 XDP 时必须关闭 HW-GRO。此前各驱动实现不一：mlx5、gve、virtio_net 拒绝挂载，bnxt、qede 在 ndo_fix_features() 中清除该 feature，而 idpf 完全不做处理。补丁在 __netdev_update_features() 中统一清除 HW-GRO，并确保 XDP setup 路径刷新 features，同时处理 mlx5 等驱动在 ndo_fix_features 中把 feature 加回来的问题。</p><blockquote><p><strong>学习价值</strong>：展示了 feature 协商机制（ndo_fix_features / __netdev_update_features）在统一驱动行为上的应用，是理解 netdev offload 框架与 XDP 约束的绝佳案例。</p></blockquote><h3 id="_6420042b5461-·-patch-net-next-v2-3-9-selftests-drv-net-drop-the-generic-xdp-hack-from-the-hw-gro-setup" tabindex="-1"><code>6420042b5461</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-4-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 3/9] selftests: drv-net: drop the generic XDP hack from the HW GRO setup</a> <a class="header-anchor" href="#_6420042b5461-·-patch-net-next-v2-3-9-selftests-drv-net-drop-the-generic-xdp-hack-from-the-hw-gro-setup" aria-label="Permalink to &quot;`6420042b5461` · [[PATCH net-next v2 3/9] selftests: drv-net: drop the generic XDP hack from the HW GRO setup](https://lore.kernel.org/all/20261122010112.1471146-4-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>HW GRO 自测需要排除 SW GRO 的干扰，此前因部分驱动将 HW GRO 与 NETIF_F_GRO 绑定，测试只能通过挂载 generic XDP 程序来间接抑制 SW GRO。现在驱动已解耦这两个 feature，测试改为直接用 ethtool 请求所需的 feature 组合，移除了 XDP hack。</p><blockquote><p><strong>学习价值</strong>：说明自测代码如何随核心语义演进而简化，同时提醒学习者 ethtool feature 控制是隔离测试网络 offload 行为的基本手段。</p></blockquote><h3 id="c912d557f20a-·-patch-net-next-v2-2-9-selftests-drv-net-gro-stats-use-the-shared-set-ethtool-feat" tabindex="-1"><code>c912d557f20a</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-3-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 2/9] selftests: drv-net: gro_stats: use the shared set_ethtool_feat()</a> <a class="header-anchor" href="#c912d557f20a-·-patch-net-next-v2-2-9-selftests-drv-net-gro-stats-use-the-shared-set-ethtool-feat" aria-label="Permalink to &quot;`c912d557f20a` · [[PATCH net-next v2 2/9] selftests: drv-net: gro_stats: use the shared set_ethtool_feat()](https://lore.kernel.org/all/20261122010112.1471146-3-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>gro_stats.py 中有一份自带的 set_ethtool_feat() 副本，且从不回读 features 验证。补丁改为复用共享 helper，使测试能像 gro_lib.py 一样检查 HW GRO 是否真正启用；当 feature 被固定时结果从 SKIP 变为 XFAIL。</p><blockquote><p><strong>学习价值</strong>：体现了内核自测基础设施中代码复用与失败语义（SKIP vs XFAIL）区分的工程实践，对编写高质量 kselftest 有参考价值。</p></blockquote><h3 id="e5d91cdb3dda-·-patch-net-next-v2-1-9-net-stop-making-hw-gro-depend-on-sw-gro" tabindex="-1"><code>e5d91cdb3dda</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-2-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 1/9] net: stop making HW-GRO depend on SW GRO</a> <a class="header-anchor" href="#e5d91cdb3dda-·-patch-net-next-v2-1-9-net-stop-making-hw-gro-depend-on-sw-gro" aria-label="Permalink to &quot;`e5d91cdb3dda` · [[PATCH net-next v2 1/9] net: stop making HW-GRO depend on SW GRO](https://lore.kernel.org/all/20261122010112.1471146-2-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>bnxt、qede 和 bnx2x 在 NETIF_F_GRO 关闭时会连带清除 NETIF_F_GRO_HW，但协议栈并无此需求：HW-GRO 的 skb 到达时已带 gso_size 聚合完成，与 LRO 帧相同，而 LRO 从不依赖 SW GRO 位。这种耦合阻碍了单独测试 HW GRO，也是 GRO 自测中 XDP hack 的根源。补丁移除了这一依赖。</p><blockquote><p><strong>学习价值</strong>：通过分析 feature 位之间的真实依赖关系（netif_elide_gro()、驱动内消费者）来解耦，是学习 feature 协商设计与 offload 数据路径的好材料。</p></blockquote><h3 id="ca8419d3f89d-·-patch-net-next-v2-0-9-net-make-core-auto-disable-hw-gro-and-lro-when-xdp-gets-attached-1" tabindex="-1"><code>ca8419d3f89d</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-1-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 0/9] net: make core auto-disable HW-GRO and LRO when XDP gets attached</a> <a class="header-anchor" href="#ca8419d3f89d-·-patch-net-next-v2-0-9-net-make-core-auto-disable-hw-gro-and-lro-when-xdp-gets-attached-1" aria-label="Permalink to &quot;`ca8419d3f89d` · [[PATCH net-next v2 0/9] net: make core auto-disable HW-GRO and LRO when XDP gets attached](https://lore.kernel.org/all/20261122010112.1471146-1-kuba@kernel.org/)&quot;">​</a></h3><p><em>Jakub Kicinski (<a href="mailto:kuba@kernel.org" target="_blank" rel="noreferrer">kuba@kernel.org</a>)｜netdev</em></p><p>本系列补丁将 XDP 挂载时自动清除 HW-GRO 和 LRO 的逻辑从各驱动上移到 netdev core，实现统一行为。原因在于 XDP 不理解 GSO 帧：GSO 帧在 XDP 看来只是大包，push/pop 头部操作无法反映到 GSO 元数据，且 struct xdp_frame 不携带 GSO 字段导致 XDP redirect 对 GSO 完全无感知。此前各驱动行为不一，有的拒绝挂载、有的自动清除。</p><blockquote><p><strong>学习价值</strong>：清晰解释了 XDP 与 GSO/GRO 的根本冲突，是理解 XDP 数据模型限制及其与 offload 交互的核心阅读材料。</p></blockquote><h3 id="b69187689364-·-patch-net-2-2-vmxnet3-keep-the-xdp-program-across-device-resets" tabindex="-1"><code>b69187689364</code> · <a href="https://lore.kernel.org/all/20261122002847.616-3-filzador@gmail.com/" target="_blank" rel="noreferrer">[PATCH net 2/2] vmxnet3: keep the XDP program across device resets</a> <a class="header-anchor" href="#b69187689364-·-patch-net-2-2-vmxnet3-keep-the-xdp-program-across-device-resets" aria-label="Permalink to &quot;`b69187689364` · [[PATCH net 2/2] vmxnet3: keep the XDP program across device resets](https://lore.kernel.org/all/20261122002847.616-3-filzador@gmail.com/)&quot;">​</a></h3><p><em>Philipp Sudakas (<a href="mailto:filzador@gmail.com" target="_blank" rel="noreferrer">filzador@gmail.com</a>)｜netdev</em></p><p>vmxnet3_rq_cleanup_all() 会清空 adapter-&gt;xdp_bpf_prog，而它被 vmxnet3_quiesce_dev() 调用，因此 MTU 变更、down/up、ring resize、reset 和 resume 都会导致驱动不再执行 XDP，但 core 仍报告程序已挂载，且程序引用被泄漏（后续 detach 因指针已为 NULL 而提前返回）。补丁使 XDP 程序在设备 reset 后得以保留。</p><blockquote><p><strong>学习价值</strong>：典型的驱动状态与 core 状态不同步导致的引用泄漏 bug，展示了 XDP 挂载生命周期管理中驱动需要遵守的契约。</p></blockquote><h3 id="_167c7ba8a034-·-patch-net-1-2-vmxnet3-drop-xdp-frames-that-do-not-fit-in-one-rx-buffer" tabindex="-1"><code>167c7ba8a034</code> · <a href="https://lore.kernel.org/all/20261122002847.616-2-filzador@gmail.com/" target="_blank" rel="noreferrer">[PATCH net 1/2] vmxnet3: drop XDP frames that do not fit in one rx buffer</a> <a class="header-anchor" href="#_167c7ba8a034-·-patch-net-1-2-vmxnet3-drop-xdp-frames-that-do-not-fit-in-one-rx-buffer" aria-label="Permalink to &quot;`167c7ba8a034` · [[PATCH net 1/2] vmxnet3: drop XDP frames that do not fit in one rx buffer](https://lore.kernel.org/all/20261122002847.616-2-filzador@gmail.com/)&quot;">​</a></h3><p><em>Philipp Sudakas (<a href="mailto:filzador@gmail.com" target="_blank" rel="noreferrer">filzador@gmail.com</a>)｜netdev</em></p><p>vmxnet3 开启 XDP 后，rx ring 0 使用 page_pool 页并按 MTU+22 分配缓冲，但设备仍接受略长的帧（实测最多 MTU+26，带 VLAN tag 时 MTU+30）并将其拆分到两个 descriptor。vmxnet3_rq_rx_complete() 只对同时置位 sop 和 eop 的完成项执行 XDP，sop 而无 eop 的帧落入 skb 路径，把 page_pool 页误当 skb 使用，导致 skb_put() 中触发 kernel BUG。补丁改为丢弃无法放入单个 rx buffer 的帧。</p><blockquote><p><strong>学习价值</strong>：展示了 page_pool 与 skb 路径混用 union 成员的危险性，以及恶意/畸形帧如何触发内核崩溃，是学习 XDP rx 路径健壮性的好案例。</p></blockquote><h3 id="f005b9b41105-·-patch-net-0-2-vmxnet3-fix-native-xdp-crash-on-oversized-frames-and-xdp-loss-on-reset-1" tabindex="-1"><code>f005b9b41105</code> · <a href="https://lore.kernel.org/all/20261122002847.616-1-filzador@gmail.com/" target="_blank" rel="noreferrer">[PATCH net 0/2] vmxnet3: fix native XDP crash on oversized frames and XDP loss on reset</a> <a class="header-anchor" href="#f005b9b41105-·-patch-net-0-2-vmxnet3-fix-native-xdp-crash-on-oversized-frames-and-xdp-loss-on-reset-1" aria-label="Permalink to &quot;`f005b9b41105` · [[PATCH net 0/2] vmxnet3: fix native XDP crash on oversized frames and XDP loss on reset](https://lore.kernel.org/all/20261122002847.616-1-filzador@gmail.com/)&quot;">​</a></h3><p><em>Philipp Sudakas (<a href="mailto:filzador@gmail.com" target="_blank" rel="noreferrer">filzador@gmail.com</a>)｜netdev</em></p><p>本系列修复 vmxnet3 native XDP 模式的两个 bug：其一，同网段任意主机发送一个超长帧（MTU 1500 时 1523-1526 字节即可）即可让 guest 内核崩溃；其二，任何设备 reset（MTU 变更、down/up、ring resize 等）后驱动静默停止执行 XDP 并泄漏程序引用。</p><blockquote><p><strong>学习价值</strong>：一个系列同时覆盖安全相关的远程崩溃漏洞和状态管理泄漏，对理解驱动 XDP 实现中的边界条件很有教学价值。</p></blockquote><h3 id="da8ec927475b-·-patch-net-next-net-zero-hw-address-entries-on-allocation" tabindex="-1"><code>da8ec927475b</code> · <a href="https://lore.kernel.org/all/20261122002633.584362-1-yuyanghuang@google.com/" target="_blank" rel="noreferrer">[PATCH net-next] net: zero hw address entries on allocation</a> <a class="header-anchor" href="#da8ec927475b-·-patch-net-next-net-zero-hw-address-entries-on-allocation" aria-label="Permalink to &quot;`da8ec927475b` · [[PATCH net-next] net: zero hw address entries on allocation](https://lore.kernel.org/all/20261122002633.584362-1-yuyanghuang@google.com/)&quot;">​</a></h3><p><em>Yuyang Huang (<a href="mailto:yuyanghuang@google.com" target="_blank" rel="noreferrer">yuyanghuang@google.com</a>)｜netdev</em></p><p>__hw_addr_create() 用 kmalloc() 分配 struct netdev_hw_addr，只拷贝 addr_len 字节到 ha-&gt;addr[MAX_ADDR_LEN]，剩余部分未初始化。若 dev-&gt;addr_len 后来增长（如对 down 状态的 TAP 设备先 SIOADDMULTI 加组播地址再通过 TUNSETLINK 切换为 ARPHRD_TUNNEL6），/proc/net/dev_mcast、AF_PACKET RTM_GETMULTICAST 及 __hw_addr_add_ex() 的 memcmp 都会泄露未初始化的 slab 字节。补丁改用 kzalloc() 修复。</p><blockquote><p><strong>学习价值</strong>：经典的内核信息泄露（KASAN/KMSAN 类）问题：结构体长度可变字段未清零加上后续长度变化即成漏洞，值得学习者举一反三。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="_90f494fdb176-·-linux-7-4-to-remove-nvme-namespaces-in-parallel-for-faster-results" tabindex="-1"><code>90f494fdb176</code> · <a href="https://www.phoronix.com/news/Linux-7.4-NVMe-NS-Parallel" target="_blank" rel="noreferrer">Linux 7.4 To Remove NVMe Namespaces In Parallel For Faster Results</a> <a class="header-anchor" href="#_90f494fdb176-·-linux-7-4-to-remove-nvme-namespaces-in-parallel-for-faster-results" aria-label="Permalink to &quot;`90f494fdb176` · [Linux 7.4 To Remove NVMe Namespaces In Parallel For Faster Results](https://www.phoronix.com/news/Linux-7.4-NVMe-NS-Parallel)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4-rc4 的 block 子系统修复中包含一项 NVMe 优化：并行移除 NVMe namespaces 以加快处理速度。该改动随本周大量 block 层 bug fix 一并进入 rc4 版本。这是存储子系统在设备管理路径上的性能改进。</p><blockquote><p><strong>学习价值</strong>：展示了 NVMe 驱动中 namespace 管理路径的并行化思路，适合学习块设备生命周期与并发处理机制。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_26fd8c00840c-·-patch-v2-rust-binder-disallow-binder-fd-transfers-1" tabindex="-1"><code>26fd8c00840c</code> · <a href="https://lore.kernel.org/all/20261121182803.2600723-1-cmllamas@google.com/" target="_blank" rel="noreferrer">[PATCH v2] rust_binder: disallow binder fd transfers</a> <a class="header-anchor" href="#_26fd8c00840c-·-patch-v2-rust-binder-disallow-binder-fd-transfers-1" aria-label="Permalink to &quot;`26fd8c00840c` · [[PATCH v2] rust_binder: disallow binder fd transfers](https://lore.kernel.org/all/20261121182803.2600723-1-cmllamas@google.com/)&quot;">​</a></h3><p><em>Carlos Llamas (<a href="mailto:cmllamas@google.com" target="_blank" rel="noreferrer">cmllamas@google.com</a>)｜rust-for-linux</em></p><p>通过 BINDER_TYPE_FD 或 BINDER_TYPE_FDA 转移 binder 设备 fd 没有合法用例，且会创建引用循环，导致排队的 transaction 未读时 Process::release() 无法执行；binder 文件还绑定到打开进程的 task、credentials 和 mmap 状态，跨进程转移破坏其 per-process 所有权模型。补丁在 Allocation::info_add_fd() 中返回 EINVAL 以禁止此类转移。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 实现中如何用简单拒绝策略消除引用循环与所有权违规，对理解 binder 生命周期模型和 Rust for Linux 的安全设计都有帮助。</p></blockquote><h3 id="_7c76966f883a-·-patch-rust-rbtree-remove-redundant-comparison-in-find-best-match" tabindex="-1"><code>7c76966f883a</code> · <a href="https://lore.kernel.org/all/20261121131618.909529-1-jfern@kernel.org/" target="_blank" rel="noreferrer">[PATCH] rust: rbtree: remove redundant comparison in find_best_match</a> <a class="header-anchor" href="#_7c76966f883a-·-patch-rust-rbtree-remove-redundant-comparison-in-find-best-match" aria-label="Permalink to &quot;`7c76966f883a` · [[PATCH] rust: rbtree: remove redundant comparison in find_best_match](https://lore.kernel.org/all/20261121131618.909529-1-jfern@kernel.org/)&quot;">​</a></h3><p><em>Joel Fernandes (<a href="mailto:jfern@kernel.org" target="_blank" rel="noreferrer">jfern@kernel.org</a>)｜rust-for-linux</em></p><p>该补丁修改了 rust/kernel/rbtree.rs 中 find_best_match() 函数的 Less 分支：原先在记录当前节点为最佳匹配前，还会比较其 key 是否小于已找到的最佳匹配的 key，但该比较永远不会失败，因此属于冗余逻辑。补丁移除了这个多余的比较，减少了一次比较操作并精简了 10 行代码。</p><blockquote><p><strong>学习价值</strong>：这是一个学习 Rust 红黑树抽象实现细节的好例子，展示了如何通过分析算法不变量（invariant）识别并消除死代码。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="_308300f47c69-·-sashiko-ai-introducing-linux-performance-specialist-review-stage" tabindex="-1"><code>308300f47c69</code> · <a href="https://www.phoronix.com/news/Sashiko-AI-Performance-Review" target="_blank" rel="noreferrer">Sashiko AI Introducing Linux Performance Specialist Review Stage</a> <a class="header-anchor" href="#_308300f47c69-·-sashiko-ai-introducing-linux-performance-specialist-review-stage" aria-label="Permalink to &quot;`308300f47c69` · [Sashiko AI Introducing Linux Performance Specialist Review Stage](https://www.phoronix.com/news/Sashiko-AI-Performance-Review)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Google 开发的 Sashiko 是面向 Linux kernel 的 agentic AI 代码审查工具，持续在内核邮件列表中发现新 bug。它新增了一个性能/基准评估技能，用于评估内核补丁的性能影响，此前还推出了实验性的补丁系列设计评估功能。</p><blockquote><p><strong>学习价值</strong>：反映了 AI 工具正深度介入内核开发流程，学习者可关注其如何辅助补丁审查与性能回归检测。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_0e90ca53e512-·-intel-linux-npu-driver-1-39-1-released-with-nova-lake-support" tabindex="-1"><code>0e90ca53e512</code> · <a href="https://www.phoronix.com/news/Intel-LInux-NPU-Driver-1.39.1" target="_blank" rel="noreferrer">Intel Linux NPU Driver 1.39.1 Released With Nova Lake Support</a> <a class="header-anchor" href="#_0e90ca53e512-·-intel-linux-npu-driver-1-39-1-released-with-nova-lake-support" aria-label="Permalink to &quot;`0e90ca53e512` · [Intel Linux NPU Driver 1.39.1 Released With Nova Lake Support](https://www.phoronix.com/news/Intel-LInux-NPU-Driver-1.39.1)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Intel 发布用户态 Linux NPU Driver 1.39.1，正式支持 Nova Lake NPU（第 6 代神经网络处理单元 IP）。相关内核侧补丁此前已合入 Intel IVPU accelerator 驱动主线，此次更新补齐了用户态驱动支持。</p><blockquote><p><strong>学习价值</strong>：可了解 NPU 加速器在内核（IVPU 驱动）与用户态驱动的分层协作方式，是学习新硬件子系统接入内核的案例。</p></blockquote><h3 id="cd6e65fc094a-·-debian-13-8-released-with-150-security-updates" tabindex="-1"><code>cd6e65fc094a</code> · <a href="https://www.phoronix.com/news/Debian-13.8-Released" target="_blank" rel="noreferrer">Debian 13.8 Released With 150+ Security Updates</a> <a class="header-anchor" href="#cd6e65fc094a-·-debian-13-8-released-with-150-security-updates" aria-label="Permalink to &quot;`cd6e65fc094a` · [Debian 13.8 Released With 150+ Security Updates](https://www.phoronix.com/news/Debian-13.8-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Debian 13.8 发布，这是 Debian 13 &quot;Trixie&quot; 的最新 ISO 刷新版，包含 150 多项安全更新和大量 bug 修复。属于发行版的常规安全更新汇总，不涉及内核新特性。</p><blockquote><p><strong>学习价值</strong>：对内核学习价值有限，仅可作为了解发行版安全更新节奏的参考。</p></blockquote><h3 id="_8275ed904936-·-kde-plasma-6-9-allows-adjusting-the-text-cursor-blinking-rate-other-improvements" tabindex="-1"><code>8275ed904936</code> · <a href="https://www.phoronix.com/news/KDE-Plasma-6.9-Cursor-Blinking" target="_blank" rel="noreferrer">KDE Plasma 6.9 Allows Adjusting The Text Cursor Blinking Rate, Other Improvements</a> <a class="header-anchor" href="#_8275ed904936-·-kde-plasma-6-9-allows-adjusting-the-text-cursor-blinking-rate-other-improvements" aria-label="Permalink to &quot;`8275ed904936` · [KDE Plasma 6.9 Allows Adjusting The Text Cursor Blinking Rate, Other Improvements](https://www.phoronix.com/news/KDE-Plasma-6.9-Cursor-Blinking)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>KDE Plasma 6.9 开发持续推进，本周新增文本光标闪烁频率调节等多项功能与修复。内容集中在桌面环境层面，与内核开发无直接关联。</p><blockquote><p><strong>学习价值</strong>：属于桌面环境新闻，对内核学习者基本无参考价值。</p></blockquote><h3 id="b34ff6291766-·-freedesktop-org-launches-redesigned-website" tabindex="-1"><code>b34ff6291766</code> · <a href="https://www.phoronix.com/news/FreeDesktop.org-Redesigned-2026" target="_blank" rel="noreferrer">FreeDesktop.org Launches Redesigned Website</a> <a class="header-anchor" href="#b34ff6291766-·-freedesktop-org-launches-redesigned-website" aria-label="Permalink to &quot;`b34ff6291766` · [FreeDesktop.org Launches Redesigned Website](https://www.phoronix.com/news/FreeDesktop.org-Redesigned-2026)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>FreeDesktop.org 完成网站改版，这是该托管 X.Org、Wayland、Mesa、PipeWire、GStreamer 等项目的平台二十多年来首次重大界面更新。仅为基础设施与外观变化。</p><blockquote><p><strong>学习价值</strong>：与内核技术无关，仅具开源生态资讯价值。</p></blockquote><h3 id="b70d141cd8bd-·-freebsd-15-2-beta-3-released-following-17-security-advisories" tabindex="-1"><code>b70d141cd8bd</code> · <a href="https://www.phoronix.com/news/FreeBSD-15.2-Beta-3" target="_blank" rel="noreferrer">FreeBSD 15.2 Beta 3 Released Following 17 Security Advisories</a> <a class="header-anchor" href="#b70d141cd8bd-·-freebsd-15-2-beta-3-released-following-17-security-advisories" aria-label="Permalink to &quot;`b70d141cd8bd` · [FreeBSD 15.2 Beta 3 Released Following 17 Security Advisories](https://www.phoronix.com/news/FreeBSD-15.2-Beta-3)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>FreeBSD 15.2 第三个 Beta 版发布，包含多项 bug 修复、更新的 OpenZFS 代码，以及针对本周公布的 17 个 FreeBSD 安全公告的修复。属于 BSD 生态的版本测试进展。</p><blockquote><p><strong>学习价值</strong>：可对比 FreeBSD 与 Linux 在安全响应和发布流程上的差异，但对 Linux 内核学习直接价值较低。</p></blockquote><h3 id="ba51276cd7c3-·-patch-v16-09-19-hid-asus-add-support-for-response-curve" tabindex="-1"><code>ba51276cd7c3</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-10-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 09/19] HID: asus: add support for response curve</a> <a class="header-anchor" href="#ba51276cd7c3-·-patch-v16-09-19-hid-asus-add-support-for-response-curve" aria-label="Permalink to &quot;`ba51276cd7c3` · [[PATCH v16 09/19] HID: asus: add support for response curve](https://lore.kernel.org/all/20261122021849.57863-10-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>该补丁（v16 系列第 9 个）为 HID asus 驱动新增 ROG Ally 设备摇杆 response curve（响应曲线）配置支持，通过 sysfs 属性暴露给用户态，修改 drivers/hid/hid-asus.c 共 266 行。由 Denis Benato 与 Luke Jones 共同开发。</p><blockquote><p><strong>学习价值</strong>：是学习 HID 驱动中 sysfs 属性设计与设备特性暴露的典型实例。</p></blockquote><h3 id="_01cdb84044a2-·-patch-v16-08-19-hid-asus-add-joysticks-anti-deadzone-configuration" tabindex="-1"><code>01cdb84044a2</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-9-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 08/19] HID: asus: add joysticks anti-deadzone configuration</a> <a class="header-anchor" href="#_01cdb84044a2-·-patch-v16-08-19-hid-asus-add-joysticks-anti-deadzone-configuration" aria-label="Permalink to &quot;`01cdb84044a2` · [[PATCH v16 08/19] HID: asus: add joysticks anti-deadzone configuration](https://lore.kernel.org/all/20261122021849.57863-9-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>该补丁（v16 系列第 8 个）为 HID asus 驱动新增 ROG Ally 摇杆 anti-deadzone（抗死区）配置功能，用于缓解摇杆长期使用后的漂移问题，同样通过 sysfs 属性供用户态配置，新增 157 行代码。</p><blockquote><p><strong>学习价值</strong>：展示了如何针对硬件老化问题（摇杆漂移）在驱动层提供可配置补偿机制，是 sysfs 接口设计的实用范例。</p></blockquote><h3 id="_2d976a39dfd3-·-patch-v16-07-19-hid-asus-add-triggers-inner-and-outer-range-configuration" tabindex="-1"><code>2d976a39dfd3</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-8-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 07/19] HID: asus: add triggers inner and outer range configuration</a> <a class="header-anchor" href="#_2d976a39dfd3-·-patch-v16-07-19-hid-asus-add-triggers-inner-and-outer-range-configuration" aria-label="Permalink to &quot;`2d976a39dfd3` · [[PATCH v16 07/19] HID: asus: add triggers inner and outer range configuration](https://lore.kernel.org/all/20261122021849.57863-8-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>该补丁（v16 系列第 7 个）为 HID asus 驱动新增 ROG Ally 背部扳机键（triggers）内外行程范围配置支持，允许用户态通过 sysfs 属性调节扳机灵敏度，新增 225 行代码。</p><blockquote><p><strong>学习价值</strong>：与同系列补丁一起构成完整的游戏手柄驱动定制化案例，适合系统学习 HID 子系统的 sysfs 扩展方法。</p></blockquote><h3 id="f2dc7cbe37ae-·-patch-v16-06-19-hid-asus-add-joysticks-inner-and-outer-range-configuration" tabindex="-1"><code>f2dc7cbe37ae</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-7-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 06/19] HID: asus: add joysticks inner and outer range configuration</a> <a class="header-anchor" href="#f2dc7cbe37ae-·-patch-v16-06-19-hid-asus-add-joysticks-inner-and-outer-range-configuration" aria-label="Permalink to &quot;`f2dc7cbe37ae` · [[PATCH v16 06/19] HID: asus: add joysticks inner and outer range configuration](https://lore.kernel.org/all/20261122021849.57863-7-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>该补丁为 ASUS ROG Ally 掌机的摇杆增加内外死区范围配置功能，通过 sysfs attributes 暴露给 userspace，允许调整摇杆灵敏度。修改集中在 drivers/hid/hid-asus.c，新增约 265 行代码。</p><blockquote><p><strong>学习价值</strong>：展示了 HID 驱动如何通过 sysfs 接口向 userspace 暴露硬件配置能力，是学习 driver-uAPI 交互设计的良好案例。</p></blockquote><h3 id="a95a69638fe8-·-patch-v16-05-19-hid-asus-add-vibration-strength-configuration" tabindex="-1"><code>a95a69638fe8</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-6-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 05/19] HID: asus: add vibration strength configuration</a> <a class="header-anchor" href="#a95a69638fe8-·-patch-v16-05-19-hid-asus-add-vibration-strength-configuration" aria-label="Permalink to &quot;`a95a69638fe8` · [[PATCH v16 05/19] HID: asus: add vibration strength configuration](https://lore.kernel.org/all/20261122021849.57863-6-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>该补丁为 ASUS ROG Ally 掌机添加振动强度配置支持，通过新增 sysfs attributes 让 userspace 可以调节马达振动强度。改动全部位于 drivers/hid/hid-asus.c，新增 171 行。</p><blockquote><p><strong>学习价值</strong>：可学习 HID 驱动中 force feedback 相关的硬件控制如何以 sysfs 形式暴露，理解设备配置接口的分层设计。</p></blockquote><h3 id="bfa744a84c8e-·-patch-v16-04-19-hid-asus-add-gamepad-configuration" tabindex="-1"><code>bfa744a84c8e</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-5-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 04/19] HID: asus: add gamepad configuration</a> <a class="header-anchor" href="#bfa744a84c8e-·-patch-v16-04-19-hid-asus-add-gamepad-configuration" aria-label="Permalink to &quot;`bfa744a84c8e` · [[PATCH v16 04/19] HID: asus: add gamepad configuration](https://lore.kernel.org/all/20261122021849.57863-5-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>该补丁为 ASUS 掌机添加 gamepad 配置的基础结构，包括能力检测、设备初始化到已知状态，并暴露 xbox_controller 属性用于读取和切换 Xbox 手柄模式。hid_asus_ally_reset_resume() 现在会等待 gamepad MCU 报告就绪，reset resume 可能返回 -ENODEV 而非总是成功。</p><blockquote><p><strong>学习价值</strong>：体现了驱动初始化状态机和错误处理路径的演进，对理解 MCU 通信与 resume 流程中的错误传播很有参考价值。</p></blockquote><h3 id="_7161ae46b829-·-patch-v16-03-19-hid-asus-add-support-for-rog-ally-handhelds" tabindex="-1"><code>7161ae46b829</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-4-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 03/19] HID: asus: add support for ROG Ally handhelds</a> <a class="header-anchor" href="#_7161ae46b829-·-patch-v16-03-19-hid-asus-add-support-for-rog-ally-handhelds" aria-label="Permalink to &quot;`7161ae46b829` · [[PATCH v16 03/19] HID: asus: add support for ROG Ally handhelds](https://lore.kernel.org/all/20261122021849.57863-4-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>该补丁为 ASUS ROG Ally 掌机实现核心功能：扩展 hid-asus 驱动、将设备初始化为 ready 状态、实现 Ally X 的 input mapping，并为 AC 按钮长按发出单一事件。每个接口保持独立状态并各自上报 evdev。</p><blockquote><p><strong>学习价值</strong>：展示了 HID input mapping 与多接口设备状态管理的实现方式，是学习 HID 子系统设备探测与事件上报的实用素材。</p></blockquote><h3 id="c9533add7acc-·-patch-v16-02-19-hid-asus-move-functions-above" tabindex="-1"><code>c9533add7acc</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-3-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 02/19] HID: asus: move functions above</a> <a class="header-anchor" href="#c9533add7acc-·-patch-v16-02-19-hid-asus-move-functions-above" aria-label="Permalink to &quot;`c9533add7acc` · [[PATCH v16 02/19] HID: asus: move functions above](https://lore.kernel.org/all/20261122021849.57863-3-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>该补丁是纯代码整理：将 hid-asus.c 中 ally 驱动需要使用的核心函数移动到调用点之前，避免使用前向声明。改动为 116 行代码的位置移动，无功能变化。</p><blockquote><p><strong>学习价值</strong>：提醒学习者内核补丁系列中代码重构与功能补丁分离的规范做法，保持每个 patch 单一职责便于 review。</p></blockquote><h3 id="b1c2403d2439-·-patch-v16-01-19-hid-asus-size-feature-reports-from-the-hid-report-descriptor" tabindex="-1"><code>b1c2403d2439</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-2-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 01/19] HID: asus: size feature reports from the HID report descriptor</a> <a class="header-anchor" href="#b1c2403d2439-·-patch-v16-01-19-hid-asus-size-feature-reports-from-the-hid-report-descriptor" aria-label="Permalink to &quot;`b1c2403d2439` · [[PATCH v16 01/19] HID: asus: size feature reports from the HID report descriptor](https://lore.kernel.org/all/20261122021849.57863-2-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>ASUS vendor protocol 在不同设备上复用相同的 feature report ID 但长度不同（如 N-KEY 键盘和 ROG Ally 的 0x5A/0x5E 为 64 字节，XG Mobile 的 0x5E 为 300 字节）。该补丁移除硬编码的传输长度，改为从 HID report descriptor 推导每个 feature report 的实际大小，避免新设备因长度不匹配而失败。</p><blockquote><p><strong>学习价值</strong>：是理解 HID report descriptor 解析与 feature report 传输机制的绝佳案例，展示了用规范方式替代硬编码的工程实践。</p></blockquote><h3 id="_4ded74b952b1-·-patch-v16-00-19-hid-asus-add-support-for-rog-ally-handhelds-1" tabindex="-1"><code>4ded74b952b1</code> · <a href="https://lore.kernel.org/all/20261122021849.57863-1-denis.benato@linux.dev/" target="_blank" rel="noreferrer">[PATCH v16 00/19] HID: asus: add support for ROG Ally handhelds</a> <a class="header-anchor" href="#_4ded74b952b1-·-patch-v16-00-19-hid-asus-add-support-for-rog-ally-handhelds-1" aria-label="Permalink to &quot;`4ded74b952b1` · [[PATCH v16 00/19] HID: asus: add support for ROG Ally handhelds](https://lore.kernel.org/all/20261122021849.57863-1-denis.benato@linux.dev/)&quot;">​</a></h3><p><em>Denis Benato (denis.benato@linux.dev)｜lkml</em></p><p>该补丁系列（共 19 个 patch）为 ASUS ROG Ally 掌机在 HID 驱动中添加完整支持，包括睡眠唤醒后的设备重初始化、gamepad 配置、振动强度、摇杆与扳机范围、anti-deadzone、response curve、force feedback、手柄模式切换、turbo 按钮和按键重映射等功能。基于 Luke Jones 的原始工作重构为可上游合入的形式。</p><blockquote><p><strong>学习价值</strong>：作为完整的驱动补丁系列，展示了从功能设计、代码重构到 uAPI 暴露的完整上游流程，适合学习大型驱动补丁的组织方式。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>f005b9b41105</code> · <a href="https://lore.kernel.org/all/20261122002847.616-1-filzador@gmail.com/" target="_blank" rel="noreferrer">[PATCH net 0/2] vmxnet3: fix native XDP crash on oversized frames and XDP loss on reset</a></li><li><code>ca8419d3f89d</code> · <a href="https://lore.kernel.org/all/20261122010112.1471146-1-kuba@kernel.org/" target="_blank" rel="noreferrer">[PATCH net-next v2 0/9] net: make core auto-disable HW-GRO and LRO when XDP gets attached</a></li><li><code>68df655238ec</code> · <a href="https://lore.kernel.org/all/20261122011809.2667684-22-jarkko@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH v6 21/26] security: Add userland LSM hooks</a></li><li><code>26fd8c00840c</code> · <a href="https://lore.kernel.org/all/20261121182803.2600723-1-cmllamas@google.com/" target="_blank" rel="noreferrer">[PATCH v2] rust_binder: disallow binder fd transfers</a></li></ul>',199)])])}const k=r(n,[["render",l]]);export{u as __pageData,k as default};
